import{_ as d,o as r,c as o,a2 as n}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"15.3 高频易错考点总结","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/15-chapter-15-li-lun-kao-shi-ying-shi-ji-qiao/15-3-gao-pin-yi-cuo-kao-dian-zong-jie.md","filePath":"electrician/low-voltage-electrician/15-chapter-15-li-lun-kao-shi-ying-shi-ji-qiao/15-3-gao-pin-yi-cuo-kao-dian-zong-jie.md","lastUpdated":1795661954000}'),s={name:"electrician/low-voltage-electrician/15-chapter-15-li-lun-kao-shi-ying-shi-ji-qiao/15-3-gao-pin-yi-cuo-kao-dian-zong-jie.md"};function a(e,t,g,h,l,i){return r(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="_15-3-高频易错考点总结" tabindex="-1">15.3 高频易错考点总结 <a class="header-anchor" href="#_15-3-高频易错考点总结" aria-label="Permalink to &quot;15.3 高频易错考点总结&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>理论考试丢分,大多不是因为&quot;没学过&quot;,而是因为<strong>记混了</strong>。这一节把最容易出错的考点按模块列出来,每条都给出&quot;错误说法 → 正确说法 → 错在哪 → 记忆口诀&quot;四步对照。考前反复看这一节,比再刷一遍正文更有效。</p><h2 id="一、法规与证件" tabindex="-1">一、法规与证件 <a class="header-anchor" href="#一、法规与证件" aria-label="Permalink to &quot;一、法规与证件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>易错说法</th><th>正确说法</th><th>为什么</th><th>口诀</th></tr></thead><tbody><tr><td>操作证有效期 3 年</td><td><strong>6 年</strong>有效</td><td>现行规定为 6 年,旧的 3 年有效期是历史规定</td><td>六证三审</td></tr><tr><td>每 6 年复审一次</td><td>每 <strong>3 年</strong>复审一次</td><td>复审周期短于有效期,6 年内要审两次</td><td>六证三审</td></tr><tr><td>年满 16 周岁可报考</td><td>年满 <strong>18 周岁</strong></td><td>特种作业属高危作业,须成年</td><td>幺八成年</td></tr><tr><td>低压/高压分界是 220V</td><td><strong>1 kV(1000V)</strong></td><td>1kV 以下为低压,1kV 及以上为高压</td><td>一千伏,分高低</td></tr><tr><td>电工证由人社部门发</td><td><strong>应急管理部门</strong>考核发证</td><td>特种作业操作证属应急管理序列</td><td>应急发证</td></tr><tr><td>操作证可以借给同事用</td><td><strong>不得转借</strong>,人证必须对应</td><td>持证上岗针对本人</td><td>人证一体</td></tr><tr><td>复审不用培训</td><td>复审前应参加<strong>必要的安全培训并考试合格</strong></td><td>复审是安全能力的再确认</td><td>复审先培训</td></tr><tr><td>没证可以先上岗再补</td><td><strong>必须持证上岗</strong></td><td>无证作业属违法行为</td><td>无证不上岗</td></tr></tbody></table><blockquote><p>💡 记两个数字:<strong>6 年</strong>有效期、<strong>3 年</strong>复审,这是法规题出现频率最高的组合。</p></blockquote><h2 id="二、安全电压与安全电流" tabindex="-1">二、安全电压与安全电流 <a class="header-anchor" href="#二、安全电压与安全电流" aria-label="Permalink to &quot;二、安全电压与安全电流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>易错说法</th><th>正确说法</th><th>为什么</th><th>口诀</th></tr></thead><tbody><tr><td>安全电压是 220V</td><td><strong>42/36/24/12/6 V</strong> 五个等级</td><td>220V 是相电压,不是安全电压</td><td>四二到六</td></tr><tr><td>36V 绝对安全,摸到没事</td><td>36V 只是<strong>一般场所</strong>的安全电压,潮湿、金属容器内还要降到 12V</td><td>&quot;安全电压&quot;是降低风险,不是绝对无危险</td><td>三六一般,十二特殊</td></tr><tr><td>一般场所行灯可用 220V</td><td>行灯电压 <strong>≤36V</strong></td><td>行灯是手持移动灯具,风险高</td><td>行灯三六</td></tr><tr><td>特别潮湿场所、金属容器内行灯也是 36V</td><td><strong>≤12V</strong></td><td>人体电阻下降,危险加倍</td><td>湿处十二</td></tr><tr><td>安全电压可用自耦调压器获得</td><td>必须用<strong>安全隔离变压器</strong></td><td>自耦变压器不隔离,一次侧故障会窜入二次侧</td><td>隔离才安全</td></tr><tr><td>感知电流约 50mA</td><td>感知电流约 <strong>1mA</strong></td><td>50mA 已是危险电流</td><td>感知一</td></tr><tr><td>摆脱电流约 1mA</td><td>摆脱电流约 <strong>10mA</strong></td><td>1mA 是感知,10mA 是能自主摆脱的上限</td><td>摆脱十</td></tr><tr><td>通过 10mA 就有生命危险</td><td>一般 <strong>50mA</strong> 以上有生命危险</td><td>30mA 以下短时间一般不致生命危险</td><td>危险五十</td></tr></tbody></table><blockquote><p>💡 电流三兄弟:<strong>感知 1mA、摆脱 10mA、危险 50mA</strong>。漏电保护器取 30mA,是兼顾人身安全和误动作的折中值。</p></blockquote><h2 id="三、接地与接零" tabindex="-1">三、接地与接零 <a class="header-anchor" href="#三、接地与接零" aria-label="Permalink to &quot;三、接地与接零&quot;">​</a></h2><table tabindex="0"><thead><tr><th>易错说法</th><th>正确说法</th><th>为什么</th><th>口诀</th></tr></thead><tbody><tr><td>保护接零适用于 IT 系统</td><td>适用于 <strong>TN 系统</strong></td><td>接零要求电源中性点直接接地并有中性线</td><td>接零找 TN</td></tr><tr><td>保护接地只用于 TN 系统</td><td>用于 <strong>TT/IT</strong> 或中性点不接地系统</td><td>中性点不接地时无法接零,只能接地</td><td>接地找 TT/IT</td></tr><tr><td>同一系统可以一部分接地、一部分接零</td><td><strong>严禁混用</strong></td><td>混用会使外壳带上危险电压</td><td>一系统一制式</td></tr><tr><td>TT 系统中设备外壳接零线</td><td>外壳<strong>独立接地</strong></td><td>TT 的中性线不引出保护功能</td><td>TT 外壳自己接地</td></tr><tr><td>TN-S 中 N 线与 PE 线合并</td><td><strong>分开敷设</strong>,五线制</td><td>S 表示 Separate,分开</td><td>S 是分开</td></tr><tr><td>TN-C 中 PEN 线只作中性线</td><td>兼作<strong>中性线和保护线</strong></td><td>C 表示 Combined,合并</td><td>C 是合并</td></tr><tr><td>接地电阻越大越好</td><td><strong>越小越好</strong></td><td>电阻越小,故障电流越容易入地,外壳电压越低</td><td>越小越好</td></tr><tr><td>保护接地电阻 ≤10Ω</td><td><strong>≤4Ω</strong></td><td>4Ω 是保护接地的通用要求</td><td>接地四,重复十</td></tr><tr><td>重复接地电阻 ≤4Ω</td><td><strong>≤10Ω</strong></td><td>重复接地是补充措施,要求略宽</td><td>接地四,重复十</td></tr></tbody></table><blockquote><p>💡 系统代号速记:<strong>IT</strong> = 电源不接地、设备接地;<strong>TT</strong> = 电源接地、设备独立接地;<strong>TN</strong> = 电源接地、设备接零(TN-S 五线、TN-C 四线)。</p></blockquote><h2 id="四、保护电器" tabindex="-1">四、保护电器 <a class="header-anchor" href="#四、保护电器" aria-label="Permalink to &quot;四、保护电器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>易错说法</th><th>正确说法</th><th>为什么</th><th>口诀</th></tr></thead><tbody><tr><td>熔断器只能短路保护</td><td>主要作短路保护,<strong>也可作过载保护</strong></td><td>过载时熔体也会因热积累熔断</td><td>熔断双保</td></tr><tr><td>热继电器能作短路保护</td><td><strong>只能作过载保护</strong></td><td>热元件有热惯性,短路时来不及动作</td><td>热继只管过载</td></tr><tr><td>接触器能切断短路电流</td><td><strong>不能</strong>,只能通断正常负载电流</td><td>接触器灭弧能力有限</td><td>接触器不扛短路</td></tr><tr><td>接触器没有失压保护</td><td><strong>有失压(欠压)保护</strong></td><td>线圈失电即释放,恢复供电不会自启动</td><td>失电即释放</td></tr><tr><td>断路器不能作过载保护</td><td><strong>能</strong>,一般兼具短路和过载保护</td><td>脱扣器分热脱扣和电磁脱扣</td><td>断路双保</td></tr><tr><td>装了漏电保护器就不用接地</td><td><strong>不能替代</strong>接地或接零</td><td>漏保是附加保护,接地是基本措施</td><td>漏保是加法</td></tr><tr><td>漏保动作电流 300mA</td><td>一般场所 <strong>30mA</strong></td><td>30mA 才能在人身触电时及时切断</td><td>三十毫安</td></tr><tr><td>漏保动作后直接合闸</td><td>先<strong>查明原因</strong>,排除故障后再送电</td><td>动作说明存在漏电或触电</td><td>先查后合</td></tr><tr><td>漏保装好就不用管</td><td>应<strong>每月</strong>按一次试验按钮</td><td>试验按钮检查脱扣机构是否有效</td><td>月月试跳</td></tr></tbody></table><blockquote><p>💡 三类保护电器分工:<strong>熔断器/断路器管短路,热继电器管过载,漏电保护器管漏电</strong>,谁也不能替代谁。</p></blockquote><h2 id="五、仪表使用" tabindex="-1">五、仪表使用 <a class="header-anchor" href="#五、仪表使用" aria-label="Permalink to &quot;五、仪表使用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>易错说法</th><th>正确说法</th><th>为什么</th><th>口诀</th></tr></thead><tbody><tr><td>电压表与被测电路串联</td><td><strong>并联</strong></td><td>电压表内阻大,并联才不影响电路</td><td>压并流串</td></tr><tr><td>电流表与被测电路并联</td><td><strong>串联</strong></td><td>电流表内阻小,并联会造成短路</td><td>压并流串</td></tr><tr><td>万用表可以带电转换量程</td><td><strong>禁止</strong>带电转换</td><td>转换瞬间可能损坏表头或触电</td><td>换挡先断电</td></tr><tr><td>钳形表可同时钳两根导线</td><td>只能钳<strong>一根</strong></td><td>两根电流方向相反会相互抵消</td><td>一钳一线</td></tr><tr><td>钳形表可带电切换量程</td><td>应<strong>退出导线后</strong>再换挡</td><td>带电换挡易产生电弧、损坏仪表</td><td>退线再换挡</td></tr><tr><td>兆欧表测前不用放电</td><td>必须<strong>断电并充分放电</strong></td><td>电容残余电荷会损坏仪表、伤人</td><td>先放电再摇表</td></tr><tr><td>兆欧表转速 60r/min</td><td>约 <strong>120r/min</strong></td><td>额定转速下测量值才准确</td><td>一百二</td></tr><tr><td>万用表可以测绝缘电阻</td><td>应使用<strong>兆欧表</strong></td><td>万用表电压低,测不出绝缘真实值</td><td>绝缘用兆欧</td></tr></tbody></table><blockquote><p>💡 仪表题的核心就一句:<strong>电压表并联、电流表串联、绝缘用兆欧表、换挡先断电</strong>。</p></blockquote><h2 id="六、线路与导线" tabindex="-1">六、线路与导线 <a class="header-anchor" href="#六、线路与导线" aria-label="Permalink to &quot;六、线路与导线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>易错说法</th><th>正确说法</th><th>为什么</th><th>口诀</th></tr></thead><tbody><tr><td>导线越细越省越好</td><td>按<strong>发热条件、电压损失、机械强度</strong>选择</td><td>过细会发热、压降大、易断</td><td>三条件定截面</td></tr><tr><td>导线接头接触电阻越大越好</td><td><strong>越小越好</strong></td><td>接触电阻大→发热→氧化→恶性循环</td><td>接头要小</td></tr><tr><td>铝线导电性能比铜线好</td><td><strong>铜线更好</strong></td><td>铜的电阻率低、抗氧化、机械强度高</td><td>铜优于铝</td></tr><tr><td>三相相线颜色随意</td><td><strong>L1 黄、L2 绿、L3 红</strong></td><td>国标规定相色,便于辨识</td><td>黄绿红</td></tr><tr><td>N 线用黄绿双色</td><td>N 线用<strong>淡蓝色</strong>,PE 用<strong>黄绿双色</strong></td><td>双色线专用于保护线,不得挪作他用</td><td>蓝零绿黄地</td></tr><tr><td>接头包不包绝缘无所谓</td><td>必须<strong>恢复绝缘</strong>,且强度不低于原导线</td><td>裸露接头易短路、触电</td><td>接头必包</td></tr><tr><td>导线可以长期超载运行</td><td>不得超过<strong>安全载流量</strong></td><td>超载发热是电气火灾主因</td><td>不超载</td></tr></tbody></table><blockquote><p>💡 颜色题记法:<strong>相线黄绿红、零线淡蓝、保护线黄绿双色</strong>。</p></blockquote><h2 id="七、变压器与电动机" tabindex="-1">七、变压器与电动机 <a class="header-anchor" href="#七、变压器与电动机" aria-label="Permalink to &quot;七、变压器与电动机&quot;">​</a></h2><table tabindex="0"><thead><tr><th>易错说法</th><th>正确说法</th><th>为什么</th><th>口诀</th></tr></thead><tbody><tr><td>变压器可以变换直流电压</td><td><strong>只能变换交流</strong></td><td>变压器靠电磁感应,需要交变磁通</td><td>变压不变直流</td></tr><tr><td>变压器油只起绝缘作用</td><td><strong>绝缘 + 冷却</strong></td><td>油既隔绝缘又传导散热</td><td>油管两件事</td></tr><tr><td>变比 K=N2/N1</td><td><strong>K=N1/N2=U1/U2</strong></td><td>一次匝数比二次匝数等于电压比</td><td>一比二</td></tr><tr><td>异步电机转速等于同步转速</td><td><strong>略低于</strong>同步转速</td><td>有转速差才能切割磁力线产生转矩</td><td>永远慢一点</td></tr><tr><td>转差率越大转速越高</td><td>转差率越大转速<strong>越低</strong></td><td>s=(n1-n)/n1,s 大说明 n 小</td><td>差大转慢</td></tr><tr><td>Y-△ 启动适用于 Y 接法电机</td><td>适用于正常运行为 <strong>△ 接法</strong>的电机</td><td>启动时先 Y 降压,运行时恢复 △</td><td>星起角跑</td></tr><tr><td>Y-△ 启动电流为直接启动的 1/2</td><td><strong>1/3</strong></td><td>星形相电压降为 1/√3,电流降为 1/3</td><td>三分之一</td></tr><tr><td>改变电压可改变转向</td><td><strong>任意对调两相</strong>电源线</td><td>改变旋转磁场方向</td><td>换两相,就反转</td></tr><tr><td>异步电机可以空载长时间运行</td><td>不宜长期空载/轻载运行</td><td>功率因数低、效率差</td><td>别空转</td></tr></tbody></table><blockquote><p>💡 电机题高频三件套:<strong>同步转速 n1=60f/p、转差率 s=(n1-n)/n1、Y-△ 启动电流降为 1/3</strong>。</p></blockquote><h2 id="八、照明与插座" tabindex="-1">八、照明与插座 <a class="header-anchor" href="#八、照明与插座" aria-label="Permalink to &quot;八、照明与插座&quot;">​</a></h2><table tabindex="0"><thead><tr><th>易错说法</th><th>正确说法</th><th>为什么</th><th>口诀</th></tr></thead><tbody><tr><td>照明开关接在零线上</td><td>必须接在<strong>相线</strong>上</td><td>开关接零线,关灯后灯头仍带电</td><td>开关控火不控零</td></tr><tr><td>螺口灯头螺纹接相线</td><td><strong>中心触点接相线</strong>,螺纹接零线</td><td>螺纹外露,接火线易触电</td><td>中心火、螺纹零</td></tr><tr><td>单相三孔插座左火右零</td><td><strong>左零右火上接地</strong></td><td>国标统一接线,便于检查</td><td>左零右火上地</td></tr><tr><td>两孔插座也有保护接地</td><td>两孔插座<strong>没有</strong>保护接地</td><td>只有相线和零线两个孔</td><td>两孔无地</td></tr><tr><td>PE 线可用淡蓝色</td><td>PE 线用<strong>黄绿双色</strong></td><td>双色是保护线专用色</td><td>双色是地</td></tr><tr><td>灯头功率可以随意加大</td><td>不得超过灯具<strong>额定功率</strong></td><td>超功率发热,可能引发火灾</td><td>不超额定</td></tr></tbody></table><blockquote><p>💡 插座接线<strong>面对插座</strong>看:左零、右火、上接地。这是&quot;面对&quot;而不是&quot;背对&quot;,题干若写&quot;背对插座&quot;要反过来判断。</p></blockquote><h2 id="九、配电与防雷接地" tabindex="-1">九、配电与防雷接地 <a class="header-anchor" href="#九、配电与防雷接地" aria-label="Permalink to &quot;九、配电与防雷接地&quot;">​</a></h2><table tabindex="0"><thead><tr><th>易错说法</th><th>正确说法</th><th>为什么</th><th>口诀</th></tr></thead><tbody><tr><td>避雷针能阻止雷云形成</td><td>作用是<strong>引雷入地</strong>,保护被保护物</td><td>避雷针是&quot;引雷针&quot;,不是&quot;消雷针&quot;</td><td>引雷入地</td></tr><tr><td>防雷装置只有避雷针</td><td>由<strong>接闪器、引下线、接地装置</strong>组成</td><td>三部分缺一不可</td><td>三件套</td></tr><tr><td>独立避雷针接地电阻 ≤30Ω</td><td><strong>≤10Ω</strong></td><td>接地电阻越小,雷电流泄放越快</td><td>防雷十欧</td></tr><tr><td>电能表测量电功率</td><td>测量<strong>电能</strong></td><td>单位是 kW·h,不是 kW</td><td>表测电能</td></tr><tr><td>电能表&quot;10(40)A&quot;中 10 是最大电流</td><td>10A 是<strong>基本电流</strong>,40A 是<strong>额定最大电流</strong></td><td>括号内为最大允许电流</td><td>括号是最大</td></tr><tr><td>避雷器离被保护设备越远越好</td><td><strong>越近越好</strong></td><td>引线越长,残压和电感压降越大</td><td>越近越好</td></tr><tr><td>防雷接地可以和其它接地共用</td><td>可以共用接地装置,但<strong>接地电阻须满足最严格的要求</strong></td><td>共用时按最小值控制</td><td>就严不就宽</td></tr></tbody></table><blockquote><p>💡 防雷三件套:<strong>接闪器(接雷)→ 引下线(导雷)→ 接地装置(泄雷)</strong>。</p></blockquote><h2 id="十、电气火灾与灭火" tabindex="-1">十、电气火灾与灭火 <a class="header-anchor" href="#十、电气火灾与灭火" aria-label="Permalink to &quot;十、电气火灾与灭火&quot;">​</a></h2><table tabindex="0"><thead><tr><th>易错说法</th><th>正确说法</th><th>为什么</th><th>口诀</th></tr></thead><tbody><tr><td>电气火灾先灭火再断电</td><td><strong>先切断电源</strong>再灭火</td><td>带电灭火有触电危险</td><td>先断电</td></tr><tr><td>带电灭火可以用泡沫灭火器</td><td>应用<strong>干粉或二氧化碳</strong>灭火器</td><td>泡沫和水导电</td><td>干粉二氧化碳</td></tr><tr><td>水可以扑救带电电气火灾</td><td><strong>带电时不能用水</strong>,断电后可以</td><td>水导电,易触电</td><td>带电禁水</td></tr><tr><td>灭火器不用检查</td><td>应<strong>定期检查</strong>压力和有效期</td><td>失效灭火器等于没有</td><td>定期查</td></tr><tr><td>火灭后可以立即恢复送电</td><td>应检查设备、排除故障后再送电</td><td>短路点未排除会复燃</td><td>查后再送</td></tr><tr><td>带电灭火可以靠近喷水</td><td>应保持<strong>安全距离</strong>并使用不导电灭火剂</td><td>电弧和跨步电压伤人</td><td>远一点</td></tr></tbody></table><blockquote><p>💡 灭火剂选择顺序:<strong>能断电 → 水也可以;不能断电 → 干粉/二氧化碳</strong>。</p></blockquote><h2 id="十一、触电急救" tabindex="-1">十一、触电急救 <a class="header-anchor" href="#十一、触电急救" aria-label="Permalink to &quot;十一、触电急救&quot;">​</a></h2><table tabindex="0"><thead><tr><th>易错说法</th><th>正确说法</th><th>为什么</th><th>口诀</th></tr></thead><tbody><tr><td>发现触电直接用手拉开</td><td>先<strong>切断电源</strong>或用<strong>绝缘物</strong>使其脱离电源</td><td>徒手救人会一起触电</td><td>先断电再救人</td></tr><tr><td>先送医院再抢救</td><td><strong>就地抢救</strong>,同时呼救</td><td>心跳呼吸停止后 4~6 分钟是黄金时间</td><td>就地抢</td></tr><tr><td>按压与吹气比例 15:2</td><td><strong>30:2</strong></td><td>现行心肺复苏标准</td><td>三十比二</td></tr><tr><td>按压频率 60 次/分</td><td><strong>100~120 次/分</strong></td><td>保证有效循环</td><td>一百到一百二</td></tr><tr><td>按压深度 2cm</td><td><strong>5~6cm</strong></td><td>深度不够无效,过深易损伤</td><td>五到六厘米</td></tr><tr><td>触电者清醒就不用管</td><td>应<strong>观察并送医</strong>,防止迟发反应</td><td>电击可能造成心律失常等迟发损伤</td><td>清醒也送医</td></tr><tr><td>触电急救要先喝水/掐人中</td><td>优先<strong>心肺复苏</strong>,不要随意喂水</td><td>意识不清时喂水会窒息</td><td>先按压</td></tr></tbody></table><blockquote><p>💡 急救顺序:<strong>脱离电源 → 判断意识和呼吸 → 呼救 → 心肺复苏(30:2)→ 送医</strong>。</p></blockquote><h2 id="十二、安全作业规范" tabindex="-1">十二、安全作业规范 <a class="header-anchor" href="#十二、安全作业规范" aria-label="Permalink to &quot;十二、安全作业规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th>易错说法</th><th>正确说法</th><th>为什么</th><th>口诀</th></tr></thead><tbody><tr><td>顺序是验电→停电</td><td><strong>停电 → 验电 → 装设接地线 → 悬挂标示牌和装设遮栏</strong></td><td>不停电无法验电,不验电无法确认无电</td><td>停验接挂</td></tr><tr><td>装设接地线先接导体端</td><td>先接<strong>接地端</strong>,后接导体端</td><td>先接地端可避免人体串入回路</td><td>先地后线</td></tr><tr><td>拆除接地线先拆接地端</td><td>先拆<strong>导体端</strong>,后拆接地端</td><td>与装设顺序相反,防止残余电荷伤人</td><td>拆时反过来</td></tr><tr><td>验电器不分电压等级</td><td>必须使用<strong>电压等级相符</strong>的验电器</td><td>低压验电器验不了高压,反之易损坏</td><td>等级相符</td></tr><tr><td>验电前不用检查验电器</td><td>应先在<strong>有电设备上验证</strong>验电器良好</td><td>防止验电器本身失效造成误判</td><td>先验器</td></tr><tr><td>可以约时停送电</td><td><strong>严禁约时停送电</strong></td><td>时间误差会造成人身伤亡</td><td>不约时</td></tr><tr><td>工作票可有可无</td><td>必须办理<strong>工作票或工作许可手续</strong></td><td>保证安全措施落实和责任明确</td><td>有票才干</td></tr><tr><td>标示牌可以随意移动</td><td><strong>不得随意移动</strong>,工作结束后由原安放人拆除</td><td>标示牌是安全措施的一部分</td><td>谁挂谁拆</td></tr><tr><td>可以单人带电作业</td><td>一般须<strong>两人及以上</strong>,一人监护</td><td>监护是最后一道防线</td><td>带电双人</td></tr></tbody></table><blockquote><p>💡 停电作业记八个字:<strong>停、验、接、挂、遮、操、护、销</strong>(停电、验电、接地、悬挂标示牌、装设遮栏、操作、监护、工作票终结)。</p></blockquote><h2 id="十三、数字速记表" tabindex="-1">十三、数字速记表 <a class="header-anchor" href="#十三、数字速记表" aria-label="Permalink to &quot;十三、数字速记表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>数值</th></tr></thead><tbody><tr><td>高低压分界</td><td>1 kV</td></tr><tr><td>安全电压等级</td><td>42 / 36 / 24 / 12 / 6 V</td></tr><tr><td>一般场所行灯电压</td><td>≤36 V</td></tr><tr><td>特别潮湿场所、金属容器内行灯</td><td>≤12 V</td></tr><tr><td>感知 / 摆脱 / 危险电流</td><td>1 / 10 / 50 mA</td></tr><tr><td>漏电保护器动作值</td><td>30 mA / ≤0.1 s</td></tr><tr><td>保护接地电阻</td><td>≤4 Ω</td></tr><tr><td>重复接地电阻</td><td>≤10 Ω</td></tr><tr><td>独立避雷针接地电阻</td><td>≤10 Ω</td></tr><tr><td>低压设备绝缘电阻</td><td>≥0.5 MΩ</td></tr><tr><td>工频频率 / 周期</td><td>50 Hz / 0.02 s</td></tr><tr><td>三相线电压 / 相电压</td><td>380 V / 220 V</td></tr><tr><td>证书有效期 / 复审周期</td><td>6 年 / 3 年</td></tr><tr><td>报考年龄 / 文化程度</td><td>满 18 周岁 / 初中及以上</td></tr><tr><td>心肺复苏按压与吹气比</td><td>30 : 2</td></tr><tr><td>按压频率 / 深度</td><td>100~120 次/分 / 5~6 cm</td></tr><tr><td>兆欧表额定转速</td><td>约 120 r/min</td></tr><tr><td>Y-△ 启动电流</td><td>直接启动的 1/3</td></tr></tbody></table><h2 id="十四、考点提示" tabindex="-1">十四、考点提示 <a class="header-anchor" href="#十四、考点提示" aria-label="Permalink to &quot;十四、考点提示&quot;">​</a></h2><ul><li>✅ 法规就记&quot;<strong>6 年有效、3 年复审、18 周岁、应急发证</strong>&quot;;</li><li>✅ 数值题集中在&quot;<strong>安全电压、安全电流、接地电阻、绝缘电阻、漏保动作值、心肺复苏</strong>&quot;;</li><li>✅ 概念题集中在&quot;<strong>保护接地 vs 保护接零、熔断器 vs 热继电器 vs 接触器、TT/TN/IT</strong>&quot;;</li><li>✅ 顺序题集中在&quot;<strong>停电检修顺序、接地线装拆顺序、触电急救顺序</strong>&quot;;</li><li>⚠️ 题干里的&quot;不属于&quot;&quot;错误的是&quot;&quot;背对插座&quot;等反向表述,是最容易看错的地方。</li></ul><h2 id="十五、本节小结" tabindex="-1">十五、本节小结 <a class="header-anchor" href="#十五、本节小结" aria-label="Permalink to &quot;十五、本节小结&quot;">​</a></h2><ul><li>易错点分十三类,其中法规数字、安全电压电流、接地接零、保护电器、操作顺序是重灾区。</li><li>每条都按&quot;错误说法 → 正确说法 → 原因 → 口诀&quot;对照记忆,比死背单句更牢。</li><li>数字速记表考前一周每天过一遍,考场上直接调用。</li><li>做完 15.4、15.5 的题后,把错题对应的条目回到本节再看一遍。</li></ul>',45)])])}const q=d(s,[["render",a]]);export{u as __pageData,q as default};
